<script setup>
import { defineAsyncComponent, computed,ref } from 'vue';
const BlockWorkspace = defineAsyncComponent(() => import('./BlockWorkspace.vue')); 
import { SCRATCH_CATEGORIES,BLOCK_SPECS,EMPTY_WORKSPACE } from '../../lib/questions/scratchBlocks.js';
const props=defineProps({modelValue:Object,disabled:Boolean});const emit=defineEmits(['update:modelValue']);const tab=ref('solution');
const value=computed(()=>props.modelValue);
function update(key,next){emit('update:modelValue',{...value.value,[key]:next});}
function config(key,next){update('block_config',{...value.value.block_config,[key]:next});}
function rule(key,next){update('block_grading',{...value.value.block_grading,[key]:next});}
function toggleCategory(id,checked){config('categories',checked?[...value.value.block_config.categories,id]:value.value.block_config.categories.filter(c=>c!==id));}
function toggleBlock(type,checked){config('allowed_types',checked?[...value.value.block_config.allowed_types,type]:value.value.block_config.allowed_types.filter(t=>t!==type));}
function workspace(next){if(tab.value==='initial')config('initial',next);else {const variants=[...value.value.block_solutions];variants[Number(tab.value==='solution'?0:tab.value)]=next;update('block_solutions',variants);}}
function addVariant(){const i=value.value.block_solutions.length;update('block_solutions',[...value.value.block_solutions,structuredClone(EMPTY_WORKSPACE)]);tab.value=String(i);}
const current=computed(()=>tab.value==='initial'?value.value.block_config.initial:value.value.block_solutions[Number(tab.value==='solution'?0:tab.value)]??EMPTY_WORKSPACE);
</script>
<template><section class="structured-question"><h3>Program blok</h3><div class="workspace-tabs"><button type="button" :class="{active:tab==='initial'}" @click="tab='initial'">Workspace awal pemain</button><button v-for="(_,i) in value.block_solutions" :key="i" type="button" :class="{active:tab===(i?String(i):'solution')}" @click="tab=i?String(i):'solution'">{{ i?'Alternatif '+i:'Kunci jawaban' }}</button><button v-if="value.block_solutions.length<4" type="button" @click="addVariant">＋ Alternatif</button></div>
<BlockWorkspace :key="tab" :model-value="current" :config="value.block_config" :disabled="disabled" :label="tab==='initial'?'Program awal':'Program jawaban benar'" @update:model-value="workspace"/>
<details><summary>Blok yang tersedia untuk pemain</summary><div class="category-choices"><section v-for="category in SCRATCH_CATEGORIES" :key="category.id"><label><input type="checkbox" :checked="value.block_config.categories.includes(category.id)" @change="toggleCategory(category.id,$event.target.checked)"/><b :style="{color:category.colour}">{{ category.name }}</b></label><label v-for="block in BLOCK_SPECS.filter(b=>b.category===category.id)" :key="block.definition.type"><input type="checkbox" :checked="value.block_config.allowed_types.includes(block.definition.type)" @change="toggleBlock(block.definition.type,$event.target.checked)"/>{{ block.definition.message0.replace(/%\d+/g,'…') }}<small>{{ block.capability==='runtime'?'Perlu runtime sprite/audio':'Struktur quiz' }}</small></label></section></div></details>
<div class="grading-options"><label><input type="checkbox" :checked="value.block_grading.check_values" @change="rule('check_values',$event.target.checked)"/>Periksa nilai input</label><label><input type="checkbox" :checked="value.block_grading.strict_order" @change="rule('strict_order',$event.target.checked)"/>Urutan harus sama</label><label><input type="checkbox" :checked="value.block_grading.allow_extra" @change="rule('allow_extra',$event.target.checked)"/>Izinkan blok tambahan</label><label><input type="checkbox" :checked="value.block_grading.partial_credit" @change="rule('partial_credit',$event.target.checked)"/>Nilai parsial</label><label>Toleransi angka<input type="number" min="0" max="1000" step="any" :value="value.block_grading.numeric_tolerance" @input="rule('numeric_tolerance',Number($event.target.value))"/></label><label>Bobot nilai<input type="number" min="1" max="100" :value="value.block_grading.weight" @input="rule('weight',Number($event.target.value))"/></label></div><p>Kunci disimpan terpisah dan hanya bisa dibaca admin. Nilai parsial tidak memberi kemenangan quiz kecuali jawaban sepenuhnya benar.</p></section></template>
<style scoped>.structured-question{min-width:0}.workspace-tabs{display:flex;gap:8px;margin:12px 0;flex-wrap:wrap}.workspace-tabs button{padding:9px 12px;background:#fff;border:1px solid #bed2c9;border-radius:6px;color:#225a44}.workspace-tabs .active{background:#245f48;color:#fff}.category-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding:16px 0}.category-choices label{display:flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:12px;margin-bottom:7px}.category-choices small{width:100%;padding-left:22px;color:#687b87}.grading-options{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.grading-options label{font-size:13px}.grading-options input[type=number]{width:85px;margin-left:8px;padding:6px}details{margin-top:16px}summary{cursor:pointer;font-weight:700;font-size:13px}p{font-size:12px;color:#597268;line-height:1.5}@media(max-width:750px){.category-choices{grid-template-columns:1fr 1fr}.grading-options{grid-template-columns:1fr}}</style>
